def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        return float(min(budget, 18.0 if hp > 3 else 42.0))

    prev_bids = []
    pressure_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp in alive_opponents:
        if opp.get('budget', 0) >= budget:
            rich_opp += 1
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            b = prev.get('bid', 0)
            prev_bids.append(b)
            if prev.get('status') == 'won' or opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                pressure_bids.append(b)

    max_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0
    pressure_prev = max(pressure_bids) if pressure_bids else max_prev

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1
    if no_water >= 2:
        danger += 3
    elif no_water >= 1:
        danger += 2

    if danger >= 5:
        base = max(pressure_prev + 2.0, avg_prev + 8.0, 0.92 * DAILY_SALARY)
    elif danger >= 3:
        base = max(avg_prev * 0.72, pressure_prev * 0.62, 0.68 * DAILY_SALARY)
    elif scarcity >= 0.7:
        base = max(avg_prev * 0.52, 0.48 * DAILY_SALARY)
    elif scarcity <= 0.25 and hp >= 5 and no_water == 0:
        base = min(avg_prev * 0.28 if avg_prev > 0 else 16.0, 0.30 * DAILY_SALARY)
    else:
        base = max(avg_prev * 0.40, 0.38 * DAILY_SALARY)

    if max_prev >= 180 and danger <= 2:
        base = min(base, 0.34 * DAILY_SALARY)
    if urgent_opp >= 2 and danger >= 3:
        base = max(base, pressure_prev + 1.5)
    if rich_opp >= 2 and danger <= 1:
        base *= 0.92
    if day >= 8 and hp >= 5 and no_water == 0:
        base *= 0.9

    reserve = 0.0
    if hp <= 4 or no_water >= 1:
        reserve = 0.0
    else:
        reserve = DAILY_SALARY * 1.2

    bid = min(base, budget - reserve)
    if bid < 0:
        bid = 0.0

    min_live_bid = 0.0
    if hp <= 2 or no_water >= 2:
        min_live_bid = 0.9 * DAILY_SALARY
    elif hp <= 4 or no_water >= 1:
        min_live_bid = 0.62 * DAILY_SALARY
    elif scarcity >= 0.7:
        min_live_bid = 0.42 * DAILY_SALARY
    else:
        min_live_bid = 12.0

    if budget <= min_live_bid:
        return float(max(0.0, budget))

    bid = max(bid, min_live_bid)
    bid = min(bid, budget)

    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    prev_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 70.0

    if my_status['hp'] < 4:
        bid = min(my_status['budget'], avg_prev * 1.2)
    elif my_status['hp'] > 8:
        bid = min(my_status['budget'], avg_prev * 0.8)
    else:
        bid = min(my_status['budget'], avg_prev * 1.05)

    return max(1.0, float(bid))
